-- Tech Stack Scout: demo workspace (20 fictional companies, 8 weekly snapshots each)
-- Run AFTER supabase-schema.sql. Insert-only and idempotent: companies whose domain
-- already exists are skipped. Demo rows carry watchlist.is_demo = true, so the weekly
-- cron (refresh_all) and request_refresh never send them to the Edge Function.
-- Open the console with ?workspace=demo (or the Live/Demo toggle) to see them.

alter table public.watchlist add column if not exists is_demo boolean not null default false;
alter table public.watchlist add column if not exists competitor text;

create or replace view public.v_accounts_ws as
select w.id, w.name, w.domain, w.segment, w.github_org, w.ats_provider, w.ats_slug, w.blog_feed,
       w.mapping_confidence, w.persona, w.stage, w.active, w.notes, w.created_at, w.last_refreshed_at,
       w.refresh_status, w.refresh_error, w.is_demo, w.competitor,
       s.id as snapshot_id, s.taken_at, s.languages, s.tech, s.ci_median_min, s.ci_repo, s.eng_roles,
       s.platform_roles, s.active_repos_30d, s.public_repos, s.blog_posts, s.evidence_tier, s.icp_fit,
       s.why_now, s.hypotheses, s.diff, s.material,
       b.id as brief_id, b.summary, b.opener, b.opener_cites, b.hook_type, b.discovery, b.verifier_passed,
       b.repaired, b.used_fallback, b.model, b.created_at as brief_at
from public.watchlist w
left join lateral (select * from public.snapshots x where x.account_id = w.id order by x.taken_at desc limit 1) s on true
left join lateral (select * from public.briefs y where y.account_id = w.id order by y.created_at desc limit 1) b on true;
grant select on public.v_accounts_ws to anon, authenticated;

create table if not exists public.demo_spec (idx int primary key, payload jsonb not null);
alter table public.demo_spec enable row level security;  -- no policies: not readable by anon

create or replace function public.seed_demo(p_weeks text[])
returns text language plpgsql security definer set search_path = public as $function$
declare
  sp record; a jsonb; acc uuid; i int; wk timestamptz; snap bigint; last_snap bigint; tech jsonb; d jsonb; st text;
  n_acc int := 0; n_snap int := 0; n_runs int := 0; brief uuid; fb text; mat boolean; nk int; nw int := array_length(p_weeks, 1);
begin
  perform setseed(0.42);
  for sp in select payload from demo_spec order by idx loop
    a := sp.payload;
    if exists (select 1 from watchlist where domain = a->>'domain') then continue; end if;
    insert into watchlist (name, domain, segment, github_org, ats_provider, ats_slug, blog_feed, mapping_confidence, persona, stage, active,
                           is_demo, competitor, created_at, refresh_status, refresh_error, notes, last_refreshed_at)
    values (a->>'name', a->>'domain', a->>'segment', a->>'github_org', a->>'ats_provider', a->>'ats_slug', a->>'blog', (a->>'mapping')::numeric,
            a->>'persona', a->>'stage', (a->>'active')::boolean, true, a->>'competitor', (p_weeks[1] || ' 02:00+00')::timestamptz - interval '6 days',
            case when a->>'error' is not null then 'error' else 'ok' end, a->>'error', 'Demo workspace · fictional company',
            (p_weeks[nw] || ' 03:18+00')::timestamptz)
    returning id into acc;
    n_acc := n_acc + 1; last_snap := null;
    for i in 1..nw loop
      st := substr(a->>'runs', i, 1);
      wk := (p_weeks[i] || ' 03:17+00')::timestamptz + make_interval(secs => floor(random() * 90)::int);
      if st = '-' then continue; end if;
      if st = 'e' then
        insert into pipeline_runs (account_id, started_at, finished_at, trigger, status, github_calls, gemini_calls, material, error, duration_ms)
        values (acc, wk, wk + interval '9 seconds', 'weekly', 'error', 13, 0, false, a->>'error', 9000 + floor(random() * 3000)::int);
        n_runs := n_runs + 1; continue;
      end if;
      select coalesce(jsonb_agg(t), '[]'::jsonb) into tech from jsonb_array_elements(a->'tech') t
        where coalesce((a->'new_at'->>(t->>'tech'))::int, -1) < i - 1;
      d := case when i = 1 then '["First snapshot"]'::jsonb else coalesce(a->'diffs'->((i - 1)::text), '[]'::jsonb) end;
      mat := i = 1 or jsonb_array_length(d) > 0 or i = nw;
      insert into snapshots (account_id, taken_at, week, languages, tech, ci_median_min, ci_runs_sampled, ci_repo, eng_roles, platform_roles,
                             active_repos_30d, public_repos, blog_posts, evidence_tier, icp_fit, why_now, hypotheses, fact_sheet_hash, material, diff)
      values (acc, wk, wk::date, a->'languages', tech, (a->'ci'->>(i - 1))::numeric, case when a->'ci'->>(i - 1) is null then null else 40 end, a->>'ci_repo',
              (a->'eng'->>(i - 1))::int, (a->'plat'->>(i - 1))::int, (a->'act'->>(i - 1))::int, (a->>'repos')::int,
              case when i = nw then a->'posts' else '[]'::jsonb end, a->>'tier',
              round(((a->>'icp')::numeric * (0.92 + 0.08 * i / nw::numeric)), 2),
              round(((a->>'why')::numeric * (0.45 + 0.55 * i / nw::numeric)), 2),
              case when i = nw then a->'hyps' else '[]'::jsonb end, md5(a->>'name' || i), mat, d)
      returning id into snap;
      n_snap := n_snap + 1; last_snap := snap;
      if i > 1 then
        insert into events (account_id, created_at, kind, detail) select acc, wk + interval '1 minute', 'change', x from jsonb_array_elements_text(d) x;
      end if;
      insert into pipeline_runs (account_id, started_at, finished_at, trigger, status, github_calls, gemini_calls, material, verifier_failed, repaired, used_fallback, duration_ms)
      values (acc, wk, wk + make_interval(secs => 8 + floor(random() * 30)::int), case when i = 1 then 'added' else 'weekly' end, 'ok',
              10 + floor(random() * 7)::int,
              case when not mat or a->>'tier' = 'C' then 0 when i = nw and ((a->'brief'->>'repaired')::boolean or (a->'brief'->>'fallback')::boolean) then 3 else 2 end,
              mat,
              i = nw and ((a->'brief'->>'repaired')::boolean or (a->'brief'->>'fallback')::boolean),
              i = nw and (a->'brief'->>'repaired')::boolean,
              i = nw and (a->'brief'->>'fallback')::boolean,
              case when mat then 21000 + floor(random() * 26000)::int else 7000 + floor(random() * 6000)::int end);
      n_runs := n_runs + 1;
    end loop;
    if last_snap is null then continue; end if;
    insert into signals (account_id, snapshot_id, fid, tech, category, state, confidence, source, strength, source_url, quote, observed_at)
      select acc, last_snap, f->>'fid', f->>'tech', f->>'category', f->>'state', (f->>'confidence')::numeric, f->>'source', f->>'strength', f->>'url', f->>'quote',
             (select taken_at from snapshots where id = last_snap) - make_interval(days => floor(random() * 20)::int)
      from jsonb_array_elements(a->'facts') f;
    insert into briefs (account_id, snapshot_id, created_at, summary, opener, opener_cites, hook_type, persona, discovery, model, prompt_version,
                        verifier_passed, verifier_errors, repaired, used_fallback)
    values (acc, last_snap, (select taken_at from snapshots where id = last_snap) + interval '40 seconds', a->'brief'->'summary', a->'brief'->>'opener',
            array(select jsonb_array_elements_text(a->'brief'->'cites')), a->'brief'->>'hook', a->>'persona', a->'brief'->'discovery',
            a->'brief'->>'model', 'writer-v1', (a->'brief'->>'passed')::boolean, a->'brief'->'errors',
            (a->'brief'->>'repaired')::boolean, (a->'brief'->>'fallback')::boolean)
    returning id into brief;
    nk := 0;
    for fb in select jsonb_array_elements_text(a->'feedback') loop
      nk := nk + 1;
      insert into feedback (brief_id, account_id, action, edited_opener, created_at)
      values (brief, acc, fb, case when fb = 'edited_tone' then (a->'brief'->>'opener') || ' Worth a 20-minute look?' end,
              (p_weeks[nw] || ' 05:00+00')::timestamptz + make_interval(hours => 26 * nk));
    end loop;
    if jsonb_typeof(a->'override') = 'array' then
      insert into overrides (account_id, tech, forced_state, note, created_at)
      values (acc, a->'override'->>0, a->'override'->>1, a->'override'->>2, (p_weeks[5] || ' 10:00+00')::timestamptz)
      on conflict do nothing;
    end if;
  end loop;
  return format('%s demo accounts, %s snapshots, %s runs', n_acc, n_snap, n_runs);
end $function$;
revoke execute on function public.seed_demo(text[]) from public, anon, authenticated;

